-- ============================================================
-- SEED EXT 3: Módulo 10 — Modais Básicos (ex 133-215)
-- Novos tópicos: modal + passivo, modal perfect (should have /
-- could have / might have), obrigação vs conselho, TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'basic-modals';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo basic-modals não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: modal + passivo
  (cid,31,133,'gap_fill','All research proposals _____ (must + submit/passive) to the ethics committee before the study begins.','must be submitted',NULL,'"Must be submitted" = strong obligation + passive.','medium'),
  (cid,31,134,'multiple_choice','Which sentence correctly uses a modal in the passive voice?','The results should be interpreted with caution given the small sample size.','["The results should interpreted with caution.","The results should be interpret with caution.","The results should be interpreted with caution given the small sample size.","The results must have been interpret with caution."]','"Should be + past participle" = modal + passive (obligation/advice).','medium'),
  (cid,31,135,'gap_fill','The error _____ (could + detect/passive) earlier if the quality control procedures had been followed.','could have been detected',NULL,'"Could have been + past participle" = past modal passive (unrealized possibility).','hard'),
  (cid,31,136,'multiple_choice','Which sentence uses "may be" (modal passive) CORRECTLY in an academic context?','The discrepancy may be explained by variation in the sample populations.','["The discrepancy may being explained by variation in sample populations.","The discrepancy may have being explained by variation.","The discrepancy may be explained by variation in the sample populations.","The discrepancy may explains by variation."]','"May be + past participle" = modal + passive for possibility in academic writing.','hard'),
  (cid,31,137,'gap_fill','Applications _____ (will + process/passive) in the order in which they are received.','will be processed',NULL,'"Will be + past participle" = future passive (certain process).','easy'),

  -- BLOCK 32: modal perfect — should have / could have / might have
  (cid,32,138,'gap_fill','You _____ (should/notify) the supervisor before changing the experimental protocol.','should have notified',NULL,'"Should have + past participle" = past obligation not fulfilled (criticism/regret).','hard'),
  (cid,32,139,'multiple_choice','What does "could have succeeded" imply?','There was a past possibility of success, but it was not realized.','["Success is certain in the future","Success is possible in the future","There was a past possibility of success, but it was not realized.","Success happened in the past"]','"Could have + past participle" = unrealized past possibility.','hard'),
  (cid,32,140,'gap_fill','She _____ (might/arrive) before the storm — we''ll never know if she tried.','might have arrived',NULL,'"Might have + past participle" = uncertain speculation about a past alternative.','hard'),
  (cid,32,141,'multiple_choice','Which sentence expresses a MISSED OBLIGATION in the past?','The researchers should have disclosed the conflict of interest at the outset.','["The researchers could have disclosed the conflict of interest.","The researchers should have disclosed the conflict of interest at the outset.","The researchers might have disclosed the conflict of interest.","The researchers must have disclosed the conflict of interest."]','"Should have + past participle" = obligation that was not met.','medium'),
  (cid,32,142,'gap_fill','The data _____ (must/misinterpret/passive) — the conclusions do not follow logically from the results.','must have been misinterpreted',NULL,'"Must have been + past participle" = strong deduction about a past event (passive).','hard'),

  -- BLOCK 33: obrigação, conselho, necessidade e proibição
  (cid,33,143,'multiple_choice','What is the difference between "must" and "have to" for obligation?','"Must" expresses internal obligation or speaker authority; "have to" expresses external obligation or rule.','["They are completely identical","''Must'' expresses internal obligation or speaker authority; ''have to'' expresses external obligation or rule.","Must is weaker than have to","Have to is more formal than must"]','"I must finish this" (personal decision) vs "I have to finish this" (external requirement).','hard'),
  (cid,33,144,'gap_fill','You _____ (mustn''t) use a mobile phone during the examination — it is strictly prohibited.','mustn''t',NULL,'"Mustn''t" = prohibition (strong negative — it is forbidden).','easy'),
  (cid,33,145,'gap_fill','You _____ (don''t have to) attend the optional lecture, but it is strongly recommended.','don''t have to',NULL,'"Don''t have to" = no obligation (it is not required, but possible).','easy'),
  (cid,33,146,'multiple_choice','Which sentence uses "ought to" correctly?','Researchers ought to disclose all funding sources to ensure transparency.','["Researchers ought disclose all funding sources.","Researchers ought to disclosing all funding sources.","Researchers ought to disclose all funding sources to ensure transparency.","Researchers ought have disclosed all funding sources."]','"Ought to + base verb" = moral advice (similar to should but slightly more formal).','medium'),
  (cid,33,147,'gap_fill','You _____ (needn''t/bring) a physical copy — electronic submission is acceptable.','needn''t bring / don''t need to bring',NULL,'"Needn''t + base verb" = no necessity (British formal).','medium'),

  -- BLOCK 34: permissão, habilidade, possibilidade (can / could / may / might)
  (cid,34,148,'gap_fill','Participants _____ (may/withdraw) from the study at any point without giving reasons.','may withdraw',NULL,'"May" = formal permission (academic/legal contexts).','easy'),
  (cid,34,149,'multiple_choice','Which sentence uses "can" vs "may" correctly for formal permission?','"May" is more formal for permission: "Participants may use calculators during the test."','["Can is always wrong for permission","Can and may are completely interchangeable in all contexts","''May'' is more formal for permission: ''Participants may use calculators during the test.''","May is used only for possibility, never permission"]','"May" = more formal permission. "Can" = informal permission.','medium'),
  (cid,34,150,'gap_fill','When she was 12, she _____ (could/speak) four languages.','could speak',NULL,'"Could" = past ability.','easy'),
  (cid,34,151,'multiple_choice','What is the difference between "can" (ability) and "could" (past ability)?','"Can" expresses present ability; "could" expresses past ability or a more tentative present possibility.','["They are identical","''Can'' expresses present ability; ''could'' expresses past ability or a more tentative present possibility.","Could is always past; can is always present with no overlap","Can is more tentative than could"]','"Can" = present ability. "Could" = past ability OR polite/tentative present possibility.','hard'),
  (cid,34,152,'gap_fill','The results _____ (might/explain) by a confounding variable not accounted for in the methodology.','might be explained',NULL,'"Might be + past participle" = uncertain possibility, academic speculation (modal + passive).','hard'),

  -- BLOCK 35: TOEFL Reading
  (cid,35,153,'multiple_choice','[TOEFL Reading] "Failure to disclose funding sources must be reported to the institutional review board immediately." "Must" here expresses:','A strong obligation imposed by institutional rules.','["A deduction","A possibility","A strong obligation imposed by institutional rules.","Advice"]','"Must" in institutional/regulatory context = strong obligation.','easy'),
  (cid,35,154,'gap_fill','[TOEFL Reading] "These results _____ (should/interpret/passive) cautiously, as the study included only a limited sample." Best form?','should be interpreted',NULL,'"Should be + past participle" = advice + passive in academic hedging.','medium'),
  (cid,35,155,'multiple_choice','[TOEFL Reading] "The breakthrough could have come sooner had funding been prioritized earlier." "Could have come" implies:','A past potential that was not realized due to insufficient funding.','["A certain past event","A future plan","A past potential that was not realized due to insufficient funding.","An obligation"]','"Could have + past participle" = unrealized past possibility.','medium'),
  (cid,35,156,'gap_fill','[TOEFL Reading] "Participants _____ (may/ask) to withdraw data at any point" — complete with the correct modal passive.','may be asked',NULL,'"May be asked" = formal permission/possibility passive.','medium'),

  -- BLOCK 36: TOEFL Speaking
  (cid,36,157,'production','[TOEFL Speaking — 45s] A reading discusses problems with healthcare access. Discuss what must be done, what should have been done earlier, and what could be done. Use: must/have to, should have + PP, could/might + base verb, should be + PP (passive).','',NULL,'Access to basic healthcare must be recognized as a fundamental right, not a privilege determined by income. Governments should have invested much more heavily in community health infrastructure decades ago — the current shortfall might have been avoided had early decisions been made differently. Today, several practical steps could address the gap: telemedicine services should be expanded to reach rural populations, pharmaceutical costs must be regulated more aggressively, and preventive care programs ought to be prioritized over expensive acute interventions. These goals might be achieved within a decade if political will is found.','hard'),
  (cid,36,158,'production','[TOEFL Speaking — 45s] A professor criticizes a student''s research design. Discuss what the student should have done differently and what could be done now. Use: should have, could have, might have, needn''t have, must have been.','',NULL,'The professor points out several significant methodological flaws. The student should have consulted with a statistician before finalizing the sample design — the power calculation was clearly insufficient. She could have increased the sample size without adding substantial cost by recruiting participants through online channels. The decision to omit a control group was critical: that must have been a fundamental oversight during the planning phase, since without it, causal claims cannot be made. She needn''t have collected data across five sites if the research question was fundamentally about a single institution. Fortunately, a partial remedy is still possible: might she reanalyze the existing data with more appropriate statistical controls? That could salvage some publishable findings.','hard'),

  -- BLOCK 37: TOEFL Writing
  (cid,37,159,'production','[TOEFL Writing — 150 words] Write an academic paragraph on "Ethical responsibilities in scientific research." Use: must (obligation), should (advice), may (permission/possibility), must have been (deduction about past), should have been (past unfulfilled obligation), modal + passive (at least twice).','',NULL,'Scientific research must be conducted according to rigorous ethical principles to maintain public trust and ensure participant welfare. Researchers should disclose all potential conflicts of interest before data collection begins, as undisclosed affiliations may influence the interpretation of results. Funding sources must be acknowledged transparently in all publications. Several high-profile cases of fabricated data suggest that oversight mechanisms should have been strengthened far earlier than they were; the damage to scientific credibility in those fields must have been immense. The current peer review process, while imperfect, should not be dismissed — it can be enhanced rather than replaced. All raw data should be made available for independent replication, and ethical approval must be obtained before any study involving human participants is initiated. Adhering to these standards may help prevent future scandals while advancing knowledge with integrity.','hard'),
  (cid,37,160,'production','[TOEFL Writing — Error Correction] Fix modal errors: "Students must to submit their assignments on time. You should have studied more before the exam (correct — no fix needed). Scientists could discovered the cure earlier. The data must been misinterpreted. You don''t must attend, but it is recommended."','',NULL,'must to submit → must submit (modal + base verb, no ''to''); should have studied = correct — no fix needed; could discovered → could have discovered (past modal: could have + past participle); must been misinterpreted → must have been misinterpreted (strong deduction: must have been + past participle); don''t must → don''t have to / mustn''t (''don''t must'' is ungrammatical — use don''t have to for ''no obligation'' or mustn''t for prohibition).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
